-- ======== PG-CFG-001  P200  Non-default server settings ========
\echo '@@CHECK PG-CFG-001'
-- check: PG-CFG-001
-- title: Non-default server settings
-- priority: 200
-- scope: setting
-- cost: 0
-- thresholds: summary_threshold
-- Inventory, not a finding: this is what you read after the problems, to
-- understand why the server behaves the way it does.
SELECT 'PG-CFG-001'::text AS check_id,
       'setting'::text    AS scope,
       s.name::text       AS object,
       format('%s = %s%s (default %s%s), set in %s%s. Context: %s.%s',
              s.name, s.setting, coalesce(' ' || s.unit, ''),
              s.boot_val, coalesce(' ' || s.unit, ''),
              s.source, coalesce(' at ' || s.sourcefile || ':' || s.sourceline::text, ''),
              s.context,
              CASE WHEN s.pending_restart THEN ' A restart is pending for this setting (PG-REL-010).' ELSE '' END) AS details,
       json_build_object('setting', s.name, 'value', s.setting, 'default', s.boot_val,
                         'reset_val', s.reset_val, 'unit', s.unit, 'source', s.source,
                         'sourcefile', s.sourcefile, 'sourceline', s.sourceline,
                         'context', s.context, 'category', s.category,
                         'pending_restart', s.pending_restart, 'vartype', s.vartype)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.source NOT IN ('default', 'override', 'client', 'session')
  AND s.setting IS DISTINCT FROM s.boot_val
  AND s.name NOT IN ('application_name', 'TimeZone', 'log_timezone', 'DateStyle', 'IntervalStyle',
                     'data_directory', 'config_file', 'hba_file', 'ident_file', 'external_pid_file',
                     'port', 'cluster_name', 'listen_addresses', 'unix_socket_directories',
                     'unix_socket_group', 'unix_socket_permissions', 'max_stack_depth',
                     'server_encoding', 'client_encoding', 'search_path', 'default_text_search_config',
                     'transaction_isolation', 'transaction_read_only', 'transaction_deferrable',
                     'lc_collate', 'lc_ctype', 'lc_messages', 'lc_monetary', 'lc_numeric', 'lc_time',
                     'ssl_cert_file', 'ssl_key_file', 'ssl_ca_file', 'ssl_crl_file', 'ssl_dh_params_file',
                     'stats_temp_directory', 'wal_segment_size', 'block_size', 'segment_size',
                     'statement_timeout', 'lock_timeout', 'idle_in_transaction_session_timeout',
                     'default_transaction_read_only', 'client_min_messages', 'jit')
ORDER BY s.category, s.name;
\echo '@@END PG-CFG-001'

-- ======== PG-CFG-002  P200  Per-database and per-role setting overrides ========
\echo '@@CHECK PG-CFG-002'
-- check: PG-CFG-002
-- title: Per-database and per-role setting overrides
-- priority: 200
-- scope: setting
-- cost: 0
SELECT 'PG-CFG-002'::text AS check_id,
       'setting'::text    AS scope,
       format('%s/%s', coalesce(d.datname, 'all databases'), coalesce(r.rolname, 'all roles'))::text AS object,
       format('An override applies to %s in %s: %s. These do not appear in postgresql.conf and do not show up in pg_settings for any other session, so a server that looks correctly configured can still behave differently for one application. Overrides of synchronous_commit, work_mem, statement_timeout, search_path and role attributes are the ones that most often surprise.',
              coalesce('role ' || r.rolname, 'every role'),
              coalesce('database ' || d.datname, 'every database'),
              array_to_string(s.setconfig, '; ')) AS details,
       json_build_object('database', d.datname, 'role', r.rolname,
                         'settings', array_to_string(s.setconfig, ';'),
                         'setting_count', cardinality(s.setconfig))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_db_role_setting s
LEFT JOIN pg_database d ON d.oid = s.setdatabase
LEFT JOIN pg_roles r    ON r.oid = s.setrole
ORDER BY coalesce(d.datname, ''), coalesce(r.rolname, '');
\echo '@@END PG-CFG-002'

-- ======== PG-CFG-004  P200  Settings applied via ALTER SYSTEM ========
SELECT (current_setting('server_version_num')::int >= 90400) AS gate_pg_cfg_004 \gset
\if :gate_pg_cfg_004
\echo '@@CHECK PG-CFG-004'
-- check: PG-CFG-004
-- title: Settings applied via ALTER SYSTEM
-- priority: 200
-- scope: setting
-- cost: 0
-- min_version: 9.4
SELECT 'PG-CFG-004'::text AS check_id,
       'setting'::text    AS scope,
       s.name::text       AS object,
       format('%s = %s%s was applied with ALTER SYSTEM (it lives in postgresql.auto.conf at line %s), not in postgresql.conf. postgresql.auto.conf is read last, so this value wins over anything configuration management writes into postgresql.conf - and configuration management will not see it, will not diff it, and will not restore it when the host is rebuilt. Default %s%s.%s',
              s.name, s.setting, coalesce(' ' || s.unit, ''), s.sourceline,
              s.boot_val, coalesce(' ' || s.unit, ''),
              CASE WHEN s.pending_restart THEN ' A restart is pending for this setting.' ELSE '' END) AS details,
       json_build_object('setting', s.name, 'value', s.setting, 'default', s.boot_val,
                         'unit', s.unit, 'sourcefile', s.sourcefile, 'sourceline', s.sourceline,
                         'context', s.context, 'pending_restart', s.pending_restart)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_settings s
WHERE s.sourcefile LIKE '%postgresql.auto.conf'
ORDER BY s.name;
\echo '@@END PG-CFG-004'
\else
\echo '@@SKIP PG-CFG-004 needs PostgreSQL 9.4 or newer'
\endif

-- ======== PG-SEC-019  P200  Login roles with expired passwords ========
\echo '@@CHECK PG-SEC-019'
-- check: PG-SEC-019
-- title: Login roles with expired passwords
-- priority: 200
-- scope: role
-- cost: 0
SELECT 'PG-SEC-019'::text AS check_id,
       'role'::text       AS scope,
       r.rolname::text    AS object,
       format('Login role %s has rolvaliduntil = %s, which passed %s ago. The role can no longer authenticate with a password, but it still exists and still holds every grant it was given, so it will silently come back to life the moment someone extends the expiry. Attributes: %s. Grants: member of %s. Currently connected: %s session(s).',
              r.rolname, r.rolvaliduntil,
              justify_interval(date_trunc('second', now() - r.rolvaliduntil)),
              coalesce(nullif(array_to_string(ARRAY[
                CASE WHEN r.rolsuper       THEN 'SUPERUSER' END,
                CASE WHEN r.rolcreaterole  THEN 'CREATEROLE' END,
                CASE WHEN r.rolcreatedb    THEN 'CREATEDB' END,
                CASE WHEN r.rolreplication THEN 'REPLICATION' END], ', '), ''), 'none'),
              coalesce((SELECT string_agg(g.rolname, ', ' ORDER BY g.rolname)
                        FROM pg_auth_members m JOIN pg_roles g ON g.oid = m.roleid
                        WHERE m.member = r.oid), 'nothing'),
              (SELECT count(*) FROM pg_stat_activity a WHERE a.usename = r.rolname)) AS details,
       json_build_object('rolname', r.rolname, 'rolvaliduntil', r.rolvaliduntil,
                         'expired_days', round(extract(epoch FROM now() - r.rolvaliduntil) / 86400)::int,
                         'rolsuper', r.rolsuper,
                         'member_of', (SELECT string_agg(g.rolname, ';' ORDER BY g.rolname)
                                       FROM pg_auth_members m JOIN pg_roles g ON g.oid = m.roleid
                                       WHERE m.member = r.oid))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_roles r
WHERE r.rolcanlogin AND r.rolvaliduntil IS NOT NULL AND r.rolvaliduntil < now()
ORDER BY r.rolvaliduntil;
\echo '@@END PG-SEC-019'

-- ======== PG-SEC-020  P200  Login roles with no password expiry ========
\echo '@@CHECK PG-SEC-020'
-- check: PG-SEC-020
-- title: Login roles with no password expiry
-- priority: 200
-- scope: role
-- cost: 0
SELECT 'PG-SEC-020'::text AS check_id,
       'role'::text       AS scope,
       NULL::text         AS object,
       format('%s of %s login roles have no rolvaliduntil set: %s. PostgreSQL has no password-age or rotation policy of its own, so an expiry date is the only server-side control over how long a credential stays valid. Most estates rotate secrets outside the database instead, which is why this is an inventory row rather than a finding: it tells a reviewer that nothing here will expire on its own. %s of these are superusers.',
              c.no_expiry, c.total,
              left(c.names, 400),
              c.supers) AS details,
       json_build_object('roles_without_expiry', c.no_expiry, 'login_roles', c.total,
                         'superusers_without_expiry', c.supers,
                         'role_names', c.names)::text AS evidence_json,
       'high'::text AS confidence
FROM (
  SELECT count(*) FILTER (WHERE rolvaliduntil IS NULL)                 AS no_expiry,
         count(*)                                                      AS total,
         count(*) FILTER (WHERE rolvaliduntil IS NULL AND rolsuper)    AS supers,
         string_agg(rolname, ', ' ORDER BY rolname) FILTER (WHERE rolvaliduntil IS NULL) AS names
  FROM pg_roles WHERE rolcanlogin
) c
WHERE c.no_expiry > 0;
\echo '@@END PG-SEC-020'

-- ======== PG-SEC-021  P200  Connection logging disabled ========
\echo '@@CHECK PG-SEC-021'
-- check: PG-SEC-021
-- title: Connection logging disabled
-- priority: 200
-- scope: setting
-- cost: 0
SELECT 'PG-SEC-021'::text        AS check_id,
       'setting'::text           AS scope,
       'log_connections'::text   AS object,
       format('log_connections = %s and log_disconnections = %s. Nothing records who connected, from where, as which role, or when they left. After an incident there is no way to answer "which credential was used and from which address" from this server''s own logs. The cost is one log line per connection, which matters only where connection churn is already high (PG-CONN-005). log_line_prefix = %s.',
              current_setting('log_connections'), current_setting('log_disconnections'),
              quote_literal(current_setting('log_line_prefix'))) AS details,
       json_build_object('log_connections', current_setting('log_connections'),
                         'log_disconnections', current_setting('log_disconnections'),
                         'log_line_prefix', current_setting('log_line_prefix'),
                         'logging_collector', current_setting('logging_collector'),
                         'log_destination', current_setting('log_destination'))::text AS evidence_json,
       'high'::text AS confidence
WHERE current_setting('log_connections') IN ('off', 'false', '0')
  AND current_setting('log_disconnections') IN ('off', 'false', '0');
\echo '@@END PG-SEC-021'

-- ======== PG-SEC-009  P230  Superuser roles ========
\echo '@@CHECK PG-SEC-009'
-- check: PG-SEC-009
-- title: Superuser roles
-- priority: 230
-- scope: role
-- cost: 0
SELECT 'PG-SEC-009'::text AS check_id,
       'role'::text       AS scope,
       r.rolname::text    AS object,
       format('Superuser with login: %s. Attributes: %s. Password: %s. Valid until: %s. Connection limit: %s. Currently connected: %s session(s). A superuser bypasses all permission checks; this row exists so a reviewer signs off on the list rather than discovering it.',
              r.rolname,
              array_to_string(ARRAY[
                CASE WHEN r.rolcreaterole  THEN 'CREATEROLE' END,
                CASE WHEN r.rolcreatedb    THEN 'CREATEDB' END,
                CASE WHEN r.rolreplication THEN 'REPLICATION' END,
                CASE WHEN r.rolbypassrls   THEN 'BYPASSRLS' END,
                CASE WHEN r.rolinherit     THEN 'INHERIT' END], ', '),
              CASE WHEN r.rolpassword IS NULL THEN 'not set' ELSE 'set' END,
              coalesce(r.rolvaliduntil::text, 'no expiry'),
              CASE WHEN r.rolconnlimit < 0 THEN 'unlimited' ELSE r.rolconnlimit::text END,
              (SELECT count(*) FROM pg_stat_activity a WHERE a.usename = r.rolname)) AS details,
       json_build_object('rolname', r.rolname, 'rolcreaterole', r.rolcreaterole,
                         'rolcreatedb', r.rolcreatedb, 'rolreplication', r.rolreplication,
                         'rolbypassrls', r.rolbypassrls, 'rolinherit', r.rolinherit,
                         'has_password', (r.rolpassword IS NOT NULL),
                         'rolvaliduntil', r.rolvaliduntil, 'rolconnlimit', r.rolconnlimit,
                         'current_sessions', (SELECT count(*) FROM pg_stat_activity a WHERE a.usename = r.rolname))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_roles r
WHERE r.rolsuper AND r.rolcanlogin
  AND r.rolname NOT IN ('rdsadmin', 'cloudsqladmin', 'cloudsqlsuperuser', 'azure_superuser',
                        'supabase_admin', 'neon_superuser', 'tsdbadmin', 'crunchy_superuser')
ORDER BY r.rolname;
\echo '@@END PG-SEC-009'

-- ======== PG-SEC-010  P230  Roles with elevated attributes ========
\echo '@@CHECK PG-SEC-010'
-- check: PG-SEC-010
-- title: Roles with elevated attributes
-- priority: 230
-- scope: role
-- cost: 0
SELECT 'PG-SEC-010'::text AS check_id,
       'role'::text       AS scope,
       r.rolname::text    AS object,
       format('Login role %s holds %s. %s Password: %s. Valid until: %s. Member of: %s.',
              r.rolname,
              array_to_string(ARRAY[
                CASE WHEN r.rolcreaterole  THEN 'CREATEROLE' END,
                CASE WHEN r.rolcreatedb    THEN 'CREATEDB' END,
                CASE WHEN r.rolreplication THEN 'REPLICATION' END,
                CASE WHEN r.rolbypassrls   THEN 'BYPASSRLS' END], ', '),
              array_to_string(ARRAY[
                CASE WHEN r.rolcreaterole  THEN 'CREATEROLE can create and alter other roles, and before PostgreSQL 16 could grant itself membership in almost any of them.' END,
                CASE WHEN r.rolreplication THEN 'REPLICATION can open a replication connection and stream the entire cluster, bypassing every table-level grant.' END,
                CASE WHEN r.rolbypassrls   THEN 'BYPASSRLS ignores every row-level security policy.' END], ' '),
              CASE WHEN r.rolpassword IS NULL THEN 'not set' ELSE 'set' END,
              coalesce(r.rolvaliduntil::text, 'no expiry'),
              coalesce((SELECT string_agg(g.rolname, ', ' ORDER BY g.rolname)
                        FROM pg_auth_members m JOIN pg_roles g ON g.oid = m.roleid
                        WHERE m.member = r.oid), 'nothing')) AS details,
       json_build_object('rolname', r.rolname, 'rolcreaterole', r.rolcreaterole,
                         'rolcreatedb', r.rolcreatedb, 'rolreplication', r.rolreplication,
                         'rolbypassrls', r.rolbypassrls,
                         'has_password', (r.rolpassword IS NOT NULL),
                         'rolvaliduntil', r.rolvaliduntil,
                         'member_of', (SELECT string_agg(g.rolname, ';' ORDER BY g.rolname)
                                       FROM pg_auth_members m JOIN pg_roles g ON g.oid = m.roleid
                                       WHERE m.member = r.oid))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_roles r
WHERE r.rolcanlogin AND NOT r.rolsuper
  AND (r.rolcreaterole OR r.rolcreatedb OR r.rolreplication OR r.rolbypassrls)
ORDER BY r.rolname;
\echo '@@END PG-SEC-010'

-- ======== PG-SEC-018  P230  Login roles with no password set ========
\echo '@@CHECK PG-SEC-018'
-- check: PG-SEC-018
-- title: Login roles with no password set
-- priority: 230
-- scope: role
-- cost: 0
-- requires: superuser
-- pg_authid.rolpassword is tested for NULL only. Its value is never read into a
-- column, a details string, or the evidence object.
SELECT 'PG-SEC-018'::text AS check_id,
       'role'::text       AS scope,
       a.rolname::text    AS object,
       format('Login role %s has no password set. That is correct when it authenticates by peer, cert, LDAP, GSSAPI or an IAM plugin, and it is a problem when it means the role was created and forgotten, or when a pg_hba rule would let it in with trust (PG-SEC-001/007). Attributes: %s. Valid until: %s. Currently connected: %s session(s). db-triage never reads the password column itself - only whether it is null.',
              a.rolname,
              coalesce(nullif(array_to_string(ARRAY[
                CASE WHEN a.rolsuper       THEN 'SUPERUSER' END,
                CASE WHEN a.rolcreaterole  THEN 'CREATEROLE' END,
                CASE WHEN a.rolcreatedb    THEN 'CREATEDB' END,
                CASE WHEN a.rolreplication THEN 'REPLICATION' END,
                CASE WHEN a.rolbypassrls   THEN 'BYPASSRLS' END], ', '), ''), 'none'),
              coalesce(a.rolvaliduntil::text, 'no expiry'),
              (SELECT count(*) FROM pg_stat_activity s WHERE s.usename = a.rolname)) AS details,
       json_build_object('rolname', a.rolname, 'has_password', false,
                         'rolsuper', a.rolsuper, 'rolcreaterole', a.rolcreaterole,
                         'rolcreatedb', a.rolcreatedb, 'rolreplication', a.rolreplication,
                         'rolbypassrls', a.rolbypassrls, 'rolvaliduntil', a.rolvaliduntil,
                         'current_sessions', (SELECT count(*) FROM pg_stat_activity s WHERE s.usename = a.rolname))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_authid a
WHERE a.rolcanlogin AND a.rolpassword IS NULL
ORDER BY a.rolsuper DESC, a.rolname;
\echo '@@END PG-SEC-018'

-- ======== PG-QRY-017  P240  Wait-event snapshot ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_qry_017 \gset
\if :gate_pg_qry_017
\echo '@@CHECK PG-QRY-017'
-- check: PG-QRY-017
-- title: Wait-event snapshot
-- priority: 240
-- scope: cluster
-- cost: 0
-- min_version: 10
SELECT 'PG-QRY-017'::text AS check_id,
       'cluster'::text    AS scope,
       coalesce(a.wait_event_type, 'CPU')::text AS object,
       format('%s session(s) in wait class %s at snapshot time %s: %s. %s',
              count(*), coalesce(a.wait_event_type, 'none (running on CPU)'),
              to_char(now(), 'YYYY-MM-DD HH24:MI:SS TZ'),
              string_agg(DISTINCT coalesce(a.wait_event, 'running'), ', '),
              CASE coalesce(a.wait_event_type, 'CPU')
                WHEN 'Lock'      THEN 'Waiting for a heavyweight lock held by another transaction: see PG-LOCK-001/002.'
                WHEN 'LWLock'    THEN 'Waiting on an internal shared-memory lock, usually buffer mapping or WAL insertion under high concurrency.'
                WHEN 'IO'        THEN 'Waiting on storage.'
                WHEN 'BufferPin' THEN 'Waiting for exclusive access to a buffer another session is reading.'
                WHEN 'Client'    THEN 'Waiting for the client to send or receive; this is application or network time, not server time.'
                WHEN 'IPC'       THEN 'Waiting for another server process, typically a parallel worker or the WAL writer.'
                WHEN 'Timeout'   THEN 'Sleeping deliberately.'
                WHEN 'Extension' THEN 'Waiting inside an extension.'
                ELSE 'One sample only: a single snapshot can miss a storm and can catch a coincidence. Deep mode samples three times.' END) AS details,
       json_build_object('wait_event_type', a.wait_event_type,
                         'sessions', count(*),
                         'wait_events', string_agg(DISTINCT coalesce(a.wait_event, 'running'), ';'),
                         'databases', string_agg(DISTINCT coalesce(a.datname, '-'), ';'),
                         'sampled_at', now())::text AS evidence_json,
       'medium'::text AS confidence
FROM pg_stat_activity a
WHERE a.state = 'active' AND a.backend_type = 'client backend' AND a.pid <> pg_backend_pid()
GROUP BY a.wait_event_type
ORDER BY count(*) DESC;
\echo '@@END PG-QRY-017'
\else
\echo '@@SKIP PG-QRY-017 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-CAP-004  P250  Database sizes ========
\echo '@@CHECK PG-CAP-004'
-- check: PG-CAP-004
-- title: Database sizes
-- priority: 250
-- scope: database
-- cost: 0
SELECT 'PG-CAP-004'::text AS check_id,
       'database'::text   AS scope,
       d.datname::text    AS object,
       format('%s: %s (%s%% of the %s cluster total across %s databases). Tablespace %s, encoding %s, collation %s, connections %s, %s.',
              d.datname, pg_size_pretty(pg_database_size(d.oid)),
              round(100.0 * pg_database_size(d.oid) / nullif(sum(pg_database_size(d.oid)) OVER (), 0), 1)::text,
              pg_size_pretty(sum(pg_database_size(d.oid)) OVER ()),
              count(*) OVER (),
              t.spcname, pg_encoding_to_char(d.encoding), d.datcollate,
              CASE WHEN d.datconnlimit < 0 THEN 'unlimited' ELSE d.datconnlimit::text END,
              CASE WHEN d.datistemplate THEN 'template database'
                   WHEN NOT d.datallowconn THEN 'connections disallowed'
                   ELSE 'ordinary database' END) AS details,
       json_build_object('datname', d.datname, 'size_bytes', pg_database_size(d.oid),
                         'cluster_bytes', sum(pg_database_size(d.oid)) OVER (),
                         'tablespace', t.spcname, 'encoding', pg_encoding_to_char(d.encoding),
                         'datcollate', d.datcollate, 'datctype', d.datctype,
                         'datconnlimit', d.datconnlimit, 'datistemplate', d.datistemplate,
                         'datallowconn', d.datallowconn, 'owner', pg_get_userbyid(d.datdba))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_database d
JOIN pg_tablespace t ON t.oid = d.dattablespace
ORDER BY pg_database_size(d.oid) DESC;
\echo '@@END PG-CAP-004'

-- ======== PG-INFO-001  P250  Server identity ========
\echo '@@CHECK PG-INFO-001'
-- check: PG-INFO-001
-- title: Server identity
-- priority: 250
-- scope: cluster
-- cost: 0
SELECT 'PG-INFO-001'::text AS check_id,
       'cluster'::text     AS scope,
       NULL::text          AS object,
       format('%s. Role: %s. Started %s (up %s). cluster_name = %s. data_checksums = %s, wal_level = %s, max_connections = %s, shared_buffers = %s, work_mem = %s, effective_cache_size = %s. Encoding %s, TimeZone %s. Worst-case memory commitment if every connection used work_mem twice: %s. Cluster holds %s across %s database(s).',
              version(),
              CASE WHEN pg_is_in_recovery() THEN 'STANDBY (in recovery)' ELSE 'PRIMARY' END,
              pg_postmaster_start_time(),
              justify_interval(date_trunc('second', now() - pg_postmaster_start_time())),
              coalesce(nullif(current_setting('cluster_name'), ''), '(unset)'),
              current_setting('data_checksums'), current_setting('wal_level'),
              current_setting('max_connections'), current_setting('shared_buffers'),
              current_setting('work_mem'), current_setting('effective_cache_size'),
              current_setting('server_encoding'), current_setting('TimeZone'),
              pg_size_pretty(((SELECT setting::bigint * 8192 FROM pg_settings WHERE name = 'shared_buffers')
                            + (SELECT setting::bigint FROM pg_settings WHERE name = 'max_connections')
                              * (SELECT setting::bigint * 1024 FROM pg_settings WHERE name = 'work_mem') * 2
                            + (SELECT setting::bigint FROM pg_settings WHERE name = 'autovacuum_max_workers')
                              * (SELECT setting::bigint * 1024 FROM pg_settings WHERE name = 'maintenance_work_mem'))::bigint),
              pg_size_pretty((SELECT sum(pg_database_size(oid)) FROM pg_database)),
              (SELECT count(*) FROM pg_database)) AS details,
       json_build_object('version', version(),
                         'server_version_num', current_setting('server_version_num')::int,
                         'in_recovery', pg_is_in_recovery(),
                         'postmaster_start_time', pg_postmaster_start_time(),
                         'uptime_seconds', round(extract(epoch FROM now() - pg_postmaster_start_time()))::bigint,
                         'cluster_name', current_setting('cluster_name'),
                         'data_checksums', current_setting('data_checksums'),
                         'wal_level', current_setting('wal_level'),
                         'max_connections', current_setting('max_connections')::int,
                         'shared_buffers_bytes', (SELECT setting::bigint * 8192 FROM pg_settings WHERE name = 'shared_buffers'),
                         'work_mem_bytes', (SELECT setting::bigint * 1024 FROM pg_settings WHERE name = 'work_mem'),
                         'effective_cache_size_bytes', (SELECT setting::bigint * 8192 FROM pg_settings WHERE name = 'effective_cache_size'),
                         'worst_case_memory_bytes',
                            ((SELECT setting::bigint * 8192 FROM pg_settings WHERE name = 'shared_buffers')
                           + (SELECT setting::bigint FROM pg_settings WHERE name = 'max_connections')
                             * (SELECT setting::bigint * 1024 FROM pg_settings WHERE name = 'work_mem') * 2
                           + (SELECT setting::bigint FROM pg_settings WHERE name = 'autovacuum_max_workers')
                             * (SELECT setting::bigint * 1024 FROM pg_settings WHERE name = 'maintenance_work_mem')),
                         'server_encoding', current_setting('server_encoding'),
                         'timezone', current_setting('TimeZone'),
                         'cluster_bytes', (SELECT sum(pg_database_size(oid)) FROM pg_database),
                         'database_count', (SELECT count(*) FROM pg_database),
                         'current_database', current_database(),
                         'connected_role', current_user,
                         'is_superuser', current_setting('is_superuser'))::text AS evidence_json,
       'high'::text AS confidence;
\echo '@@END PG-INFO-001'

-- ======== PG-INFO-003  P250  Installed extensions ========
\echo '@@CHECK PG-INFO-003'
-- check: PG-INFO-003
-- title: Installed extensions
-- priority: 250
-- scope: database
-- cost: 0
SELECT 'PG-INFO-003'::text AS check_id,
       'database'::text    AS scope,
       format('%I.extension:%s', current_database(), e.extname)::text AS object,
       format('%s version %s in schema %s, owned by %s. Server provides %s%s. %s%s',
              e.extname, e.extversion, n.nspname, pg_get_userbyid(e.extowner),
              coalesce(a.default_version, 'no version'),
              CASE WHEN a.default_version IS DISTINCT FROM e.extversion THEN ' (an update is available, PG-REL-008)' ELSE '' END,
              coalesce(nullif(a.comment, ''), 'No description.'),
              CASE WHEN current_setting('shared_preload_libraries') LIKE '%' || e.extname || '%'
                   THEN ' Loaded via shared_preload_libraries.' ELSE '' END) AS details,
       json_build_object('extname', e.extname, 'installed_version', e.extversion,
                         'default_version', a.default_version, 'schema', n.nspname,
                         'owner', pg_get_userbyid(e.extowner),
                         'preloaded', current_setting('shared_preload_libraries') LIKE '%' || e.extname || '%',
                         'update_available', a.default_version IS DISTINCT FROM e.extversion,
                         'comment', a.comment, 'database', current_database())::text AS evidence_json,
       'high'::text AS confidence
FROM pg_extension e
JOIN pg_namespace n            ON n.oid = e.extnamespace
LEFT JOIN pg_available_extensions a ON a.name = e.extname
ORDER BY e.extname;
\echo '@@END PG-INFO-003'

-- ======== PG-INFO-004  P250  Replication topology ========
\echo '@@CHECK PG-INFO-004'
-- check: PG-INFO-004
-- title: Replication topology
-- priority: 250
-- scope: cluster
-- cost: 0
-- primary_conninfo is emitted with any password removed; db-triage never
-- reports a credential.
SELECT 'PG-INFO-004'::text AS check_id,
       'cluster'::text     AS scope,
       NULL::text          AS object,
       format('This node is a %s. Connected standbys (%s): %s. Replication slots (%s): %s. Upstream: %s. synchronous_standby_names = %s, synchronous_commit = %s. Publications (%s): %s. Subscriptions (%s): %s.',
              CASE WHEN pg_is_in_recovery() THEN 'STANDBY' ELSE 'PRIMARY' END,
              (SELECT count(*) FROM pg_stat_replication),
              coalesce((SELECT string_agg(format('%s at %s [state %s, sync %s, replay lag %s, %s behind]',
                                                 coalesce(nullif(application_name, ''), 'unnamed'),
                                                 coalesce(host(client_addr), 'local'), state, sync_state,
                                                 coalesce(replay_lag::text, 'unknown'),
                                                 coalesce(pg_size_pretty(greatest(pg_wal_lsn_diff(sent_lsn, replay_lsn), 0)::bigint), '?')),
                                          '; ' ORDER BY application_name)
                        FROM pg_stat_replication), 'none'),
              (SELECT count(*) FROM pg_replication_slots),
              coalesce((SELECT string_agg(format('%s [%s%s, active=%s]', slot_name, slot_type,
                                                 coalesce('/' || plugin, ''), active), '; ' ORDER BY slot_name)
                        FROM pg_replication_slots), 'none'),
              coalesce(regexp_replace(nullif(current_setting('primary_conninfo'), ''),
                                      '(password|passfile)\s*=\s*''?[^'' ]+''?', '\1=<redacted>', 'gi'),
                       'none (this node has no upstream configured)'),
              coalesce(nullif(current_setting('synchronous_standby_names'), ''), '(empty)'),
              current_setting('synchronous_commit'),
              (SELECT count(*) FROM pg_publication),
              coalesce((SELECT string_agg(pubname, ', ' ORDER BY pubname) FROM pg_publication), 'none'),
              (SELECT count(*) FROM pg_subscription),
              coalesce((SELECT string_agg(format('%s [enabled=%s]', subname, subenabled), ', ' ORDER BY subname)
                        FROM pg_subscription), 'none')) AS details,
       json_build_object('in_recovery', pg_is_in_recovery(),
                         'standby_count', (SELECT count(*) FROM pg_stat_replication),
                         'slot_count', (SELECT count(*) FROM pg_replication_slots),
                         'inactive_slot_count', (SELECT count(*) FROM pg_replication_slots WHERE NOT active),
                         'publication_count', (SELECT count(*) FROM pg_publication),
                         'subscription_count', (SELECT count(*) FROM pg_subscription),
                         'synchronous_standby_names', current_setting('synchronous_standby_names'),
                         'synchronous_commit', current_setting('synchronous_commit'),
                         'max_wal_senders', current_setting('max_wal_senders')::int,
                         'max_replication_slots', current_setting('max_replication_slots')::int,
                         'wal_level', current_setting('wal_level'),
                         'primary_conninfo_redacted',
                            regexp_replace(current_setting('primary_conninfo'),
                                           '(password|passfile)\s*=\s*''?[^'' ]+''?', '\1=<redacted>', 'gi'))::text AS evidence_json,
       'high'::text AS confidence;
\echo '@@END PG-INFO-004'

-- ======== PG-INFO-005  P250  Connection summary ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_info_005 \gset
\if :gate_pg_info_005
\echo '@@CHECK PG-INFO-005'
-- check: PG-INFO-005
-- title: Connection summary
-- priority: 250
-- scope: cluster
-- cost: 0
-- min_version: 10
-- thresholds: top_n
SELECT 'PG-INFO-005'::text AS check_id,
       'cluster'::text     AS scope,
       NULL::text          AS object,
       format('%s client backends of a maximum of %s, plus %s background processes. By state: %s. By database: %s. Top %s application names: %s. %s distinct client addresses. Oldest connection opened %s ago.',
              c.clients, current_setting('max_connections'), c.background,
              coalesce(c.by_state, 'none'), coalesce(c.by_db, 'none'),
              :'pg_info_005_top_n'::text, coalesce(c.by_app, 'none'),
              c.distinct_addrs,
              coalesce(justify_interval(date_trunc('second', c.oldest))::text, 'n/a')) AS details,
       json_build_object('client_backends', c.clients, 'background_processes', c.background,
                         'max_connections', current_setting('max_connections')::int,
                         'by_state', c.by_state, 'by_database', c.by_db,
                         'top_applications', c.by_app,
                         'distinct_client_addrs', c.distinct_addrs,
                         'oldest_connection_seconds', round(extract(epoch FROM c.oldest))::bigint,
                         'sampled_at', now())::text AS evidence_json,
       'high'::text AS confidence
FROM (
  SELECT count(*) FILTER (WHERE backend_type = 'client backend')  AS clients,
         count(*) FILTER (WHERE backend_type <> 'client backend') AS background,
         count(DISTINCT client_addr)                              AS distinct_addrs,
         max(now() - backend_start)                               AS oldest,
         (SELECT string_agg(format('%s=%s', coalesce(state, 'unknown'), n), ', ' ORDER BY n DESC)
          FROM (SELECT state, count(*) n FROM pg_stat_activity
                WHERE backend_type = 'client backend' GROUP BY state) x)     AS by_state,
         (SELECT string_agg(format('%s=%s', coalesce(datname, '-'), n), ', ' ORDER BY n DESC)
          FROM (SELECT datname, count(*) n FROM pg_stat_activity
                WHERE backend_type = 'client backend' GROUP BY datname) y)   AS by_db,
         (SELECT string_agg(format('%s=%s', app, n), ', ' ORDER BY n DESC)
          FROM (SELECT coalesce(nullif(application_name, ''), '(none)') AS app, count(*) n
                FROM pg_stat_activity WHERE backend_type = 'client backend'
                GROUP BY 1 ORDER BY count(*) DESC LIMIT 10) z)               AS by_app
  FROM pg_stat_activity
) c;
\echo '@@END PG-INFO-005'
\else
\echo '@@SKIP PG-INFO-005 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-INFO-006  P250  Autovacuum configuration ========
\echo '@@CHECK PG-INFO-006'
-- check: PG-INFO-006
-- title: Autovacuum configuration
-- priority: 250
-- scope: setting
-- cost: 0
SELECT 'PG-INFO-006'::text AS check_id,
       'setting'::text     AS scope,
       'autovacuum'::text  AS object,
       format('autovacuum = %s, track_counts = %s, %s workers, naptime %s. Vacuum trigger: threshold %s + scale_factor %s x live rows. Analyze trigger: threshold %s + scale_factor %s x live rows. Insert trigger: %s + %s x rows. Freeze: freeze_max_age %s, multixact_freeze_max_age %s, freeze_min_age %s, table_age %s. Cost limiting: delay %s ms, limit %s (page_hit %s, page_miss %s, page_dirty %s), giving about %s MB/s of dirty pages per worker. Memory: autovacuum_work_mem %s, maintenance_work_mem %s. Logging: log_autovacuum_min_duration %s. %s relation(s) in this database override these with storage parameters (PG-CFG-003).',
              current_setting('autovacuum'), current_setting('track_counts'),
              current_setting('autovacuum_max_workers'), current_setting('autovacuum_naptime'),
              current_setting('autovacuum_vacuum_threshold'), current_setting('autovacuum_vacuum_scale_factor'),
              current_setting('autovacuum_analyze_threshold'), current_setting('autovacuum_analyze_scale_factor'),
              coalesce((SELECT setting FROM pg_settings WHERE name = 'autovacuum_vacuum_insert_threshold'), 'n/a (PostgreSQL 13+)'),
              coalesce((SELECT setting FROM pg_settings WHERE name = 'autovacuum_vacuum_insert_scale_factor'), 'n/a'),
              current_setting('autovacuum_freeze_max_age'), current_setting('autovacuum_multixact_freeze_max_age'),
              current_setting('vacuum_freeze_min_age'), current_setting('vacuum_freeze_table_age'),
              (SELECT setting FROM pg_settings WHERE name = 'autovacuum_vacuum_cost_delay'),
              (SELECT setting FROM pg_settings WHERE name = 'autovacuum_vacuum_cost_limit'),
              current_setting('vacuum_cost_page_hit'), current_setting('vacuum_cost_page_miss'),
              current_setting('vacuum_cost_page_dirty'),
              round(((CASE WHEN (SELECT setting::int FROM pg_settings WHERE name = 'autovacuum_vacuum_cost_limit') < 0
                           THEN (SELECT setting::numeric FROM pg_settings WHERE name = 'vacuum_cost_limit')
                           ELSE (SELECT setting::numeric FROM pg_settings WHERE name = 'autovacuum_vacuum_cost_limit') END)
                     / (SELECT setting::numeric FROM pg_settings WHERE name = 'vacuum_cost_page_dirty'))
                    * (1000.0 / greatest((SELECT setting::numeric FROM pg_settings WHERE name = 'autovacuum_vacuum_cost_delay'), 0.1))
                    * current_setting('block_size')::numeric / 1048576.0, 1)::text,
              current_setting('autovacuum_work_mem'), current_setting('maintenance_work_mem'),
              current_setting('log_autovacuum_min_duration'),
              (SELECT count(*) FROM pg_class WHERE array_to_string(reloptions, ' ') LIKE '%autovacuum%')) AS details,
       json_build_object('autovacuum', current_setting('autovacuum'),
                         'track_counts', current_setting('track_counts'),
                         'autovacuum_max_workers', current_setting('autovacuum_max_workers')::int,
                         'autovacuum_naptime', current_setting('autovacuum_naptime'),
                         'autovacuum_vacuum_threshold', current_setting('autovacuum_vacuum_threshold')::bigint,
                         'autovacuum_vacuum_scale_factor', current_setting('autovacuum_vacuum_scale_factor')::numeric,
                         'autovacuum_analyze_threshold', current_setting('autovacuum_analyze_threshold')::bigint,
                         'autovacuum_analyze_scale_factor', current_setting('autovacuum_analyze_scale_factor')::numeric,
                         'autovacuum_freeze_max_age', current_setting('autovacuum_freeze_max_age')::bigint,
                         'autovacuum_multixact_freeze_max_age', current_setting('autovacuum_multixact_freeze_max_age')::bigint,
                         'autovacuum_vacuum_cost_delay_ms', (SELECT setting::numeric FROM pg_settings WHERE name = 'autovacuum_vacuum_cost_delay'),
                         'autovacuum_vacuum_cost_limit', (SELECT setting::int FROM pg_settings WHERE name = 'autovacuum_vacuum_cost_limit'),
                         'vacuum_cost_limit', (SELECT setting::int FROM pg_settings WHERE name = 'vacuum_cost_limit'),
                         'relations_with_overrides', (SELECT count(*) FROM pg_class WHERE array_to_string(reloptions, ' ') LIKE '%autovacuum%'))::text AS evidence_json,
       'high'::text AS confidence;
\echo '@@END PG-INFO-006'

-- ======== PG-INFO-007  P250  Object counts ========
\echo '@@CHECK PG-INFO-007'
-- check: PG-INFO-007
-- title: Object counts
-- priority: 250
-- scope: database
-- cost: 1
SELECT 'PG-INFO-007'::text  AS check_id,
       'database'::text     AS scope,
       current_database()::text AS object,
       format('Database %s (%s): %s ordinary tables, %s partitioned tables, %s partitions, %s indexes, %s views, %s materialized views, %s sequences, %s foreign tables, %s toast tables. %s user schemas, %s user functions, %s triggers, %s foreign-key constraints. Total pg_class rows: %s.',
              current_database(), pg_size_pretty(pg_database_size(current_database())),
              c.tables, c.partitioned, c.partitions, c.indexes, c.views, c.matviews,
              c.sequences, c.foreign_tables, c.toast,
              (SELECT count(*) FROM pg_namespace WHERE nspname NOT LIKE 'pg\_%' AND nspname <> 'information_schema'),
              (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
               WHERE n.nspname NOT IN ('pg_catalog', 'information_schema')),
              (SELECT count(*) FROM pg_trigger WHERE NOT tgisinternal),
              (SELECT count(*) FROM pg_constraint WHERE contype = 'f'),
              c.total) AS details,
       json_build_object('database', current_database(),
                         'database_bytes', pg_database_size(current_database()),
                         'tables', c.tables, 'partitioned_tables', c.partitioned, 'partitions', c.partitions,
                         'indexes', c.indexes, 'views', c.views, 'matviews', c.matviews,
                         'sequences', c.sequences, 'foreign_tables', c.foreign_tables,
                         'toast_tables', c.toast, 'pg_class_rows', c.total,
                         'schemas', (SELECT count(*) FROM pg_namespace
                                     WHERE nspname NOT LIKE 'pg\_%' AND nspname <> 'information_schema'),
                         'functions', (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
                                       WHERE n.nspname NOT IN ('pg_catalog', 'information_schema')),
                         'triggers', (SELECT count(*) FROM pg_trigger WHERE NOT tgisinternal),
                         'foreign_keys', (SELECT count(*) FROM pg_constraint WHERE contype = 'f'))::text AS evidence_json,
       'high'::text AS confidence
FROM (
  SELECT count(*) AS total,
         count(*) FILTER (WHERE relkind = 'r' AND NOT relispartition) AS tables,
         count(*) FILTER (WHERE relkind = 'p')                        AS partitioned,
         count(*) FILTER (WHERE relispartition)                       AS partitions,
         count(*) FILTER (WHERE relkind = 'i')                        AS indexes,
         count(*) FILTER (WHERE relkind = 'v')                        AS views,
         count(*) FILTER (WHERE relkind = 'm')                        AS matviews,
         count(*) FILTER (WHERE relkind = 'S')                        AS sequences,
         count(*) FILTER (WHERE relkind = 'f')                        AS foreign_tables,
         count(*) FILTER (WHERE relkind = 't')                        AS toast
  FROM pg_class
) c;
\echo '@@END PG-INFO-007'

-- ======== PG-INFO-008  P250  Checkpoint, background writer, WAL and archiver rates ========
\echo '@@CHECK PG-INFO-008'
-- check: PG-INFO-008
-- title: Checkpoint, background writer, WAL and archiver rates
-- priority: 250
-- scope: cluster
-- cost: 0
-- PostgreSQL 17 split pg_stat_bgwriter into pg_stat_bgwriter and
-- pg_stat_checkpointer and renamed the checkpoint counters.
\set ON_ERROR_STOP off
SELECT (current_setting('server_version_num')::int >= 170000) AS pg_info_008_pg17 \gset
SELECT (current_setting('server_version_num')::int >= 140000) AS pg_info_008_has_stat_wal \gset
WITH ck AS (
\if :pg_info_008_pg17
  SELECT num_timed AS timed, num_requested AS requested,
         write_time::numeric AS write_time, sync_time::numeric AS sync_time,
         buffers_written AS buffers_checkpoint, stats_reset
  FROM pg_stat_checkpointer
\else
  SELECT checkpoints_timed AS timed, checkpoints_req AS requested,
         checkpoint_write_time::numeric AS write_time, checkpoint_sync_time::numeric AS sync_time,
         buffers_checkpoint, stats_reset
  FROM pg_stat_bgwriter
\endif
),
bg AS (SELECT buffers_clean, maxwritten_clean, buffers_alloc, stats_reset FROM pg_stat_bgwriter),
wl AS (
\if :pg_info_008_has_stat_wal
  SELECT wal_records, wal_fpi, wal_bytes::numeric AS wal_bytes, wal_buffers_full, stats_reset FROM pg_stat_wal
\else
  SELECT NULL::bigint AS wal_records, NULL::bigint AS wal_fpi, NULL::numeric AS wal_bytes,
         NULL::bigint AS wal_buffers_full, NULL::timestamptz AS stats_reset
\endif
),
ar AS (SELECT archived_count, failed_count, last_archived_time, last_failed_time, stats_reset FROM pg_stat_archiver),
w AS (SELECT greatest(extract(epoch FROM now() - coalesce((SELECT stats_reset FROM ck), pg_postmaster_start_time())) / 3600.0, 0.01) AS hours)
SELECT 'PG-INFO-008'::text AS check_id,
       'cluster'::text     AS scope,
       NULL::text          AS object,
       format('Counters cover %s hours since %s. Checkpoints: %s timed + %s requested = %s per hour; average write phase %s ms, sync phase %s ms; %s buffers written by the checkpointer. Background writer: %s buffers cleaned, %s rounds stopped at bgwriter_lru_maxpages, %s buffers allocated. WAL: %s. Archiver: %s archived, %s failed%s.',
              round(w.hours, 1)::text,
              coalesce(ck.stats_reset::text, 'the last statistics reset'),
              to_char(ck.timed, 'FM999,999,999'), to_char(ck.requested, 'FM999,999,999'),
              round((ck.timed + ck.requested) / w.hours, 2)::text,
              round(ck.write_time / nullif(ck.timed + ck.requested, 0), 1)::text,
              round(ck.sync_time / nullif(ck.timed + ck.requested, 0), 1)::text,
              to_char(ck.buffers_checkpoint, 'FM999,999,999,999'),
              to_char(bg.buffers_clean, 'FM999,999,999,999'),
              to_char(bg.maxwritten_clean, 'FM999,999,999,999'),
              to_char(bg.buffers_alloc, 'FM999,999,999,999'),
              CASE WHEN wl.wal_bytes IS NULL THEN 'pg_stat_wal is PostgreSQL 14 and newer; not available here'
                   ELSE format('%s total, %s per hour, %s records of which %s were full-page images (%s%%), %s buffer-full events',
                               pg_size_pretty(wl.wal_bytes::bigint),
                               pg_size_pretty((wl.wal_bytes / w.hours)::bigint),
                               to_char(wl.wal_records, 'FM999,999,999,999'),
                               to_char(wl.wal_fpi, 'FM999,999,999,999'),
                               round(100.0 * wl.wal_fpi / nullif(wl.wal_records, 0), 1)::text,
                               to_char(wl.wal_buffers_full, 'FM999,999,999,999')) END,
              to_char(ar.archived_count, 'FM999,999,999,999'), to_char(ar.failed_count, 'FM999,999,999,999'),
              coalesce(', last success ' || ar.last_archived_time::text, ' (archive_mode = ' || current_setting('archive_mode') || ')')) AS details,
       json_build_object('window_hours', round(w.hours, 2),
                         'checkpoints_timed', ck.timed, 'checkpoints_requested', ck.requested,
                         'checkpoints_per_hour', round((ck.timed + ck.requested) / w.hours, 3),
                         'avg_checkpoint_write_ms', round(ck.write_time / nullif(ck.timed + ck.requested, 0), 2),
                         'avg_checkpoint_sync_ms', round(ck.sync_time / nullif(ck.timed + ck.requested, 0), 2),
                         'buffers_checkpoint', ck.buffers_checkpoint,
                         'buffers_clean', bg.buffers_clean, 'maxwritten_clean', bg.maxwritten_clean,
                         'buffers_alloc', bg.buffers_alloc,
                         'wal_bytes', wl.wal_bytes::bigint, 'wal_records', wl.wal_records,
                         'wal_fpi', wl.wal_fpi, 'wal_buffers_full', wl.wal_buffers_full,
                         'wal_bytes_per_hour', (wl.wal_bytes / w.hours)::bigint,
                         'archived_count', ar.archived_count, 'failed_count', ar.failed_count,
                         'last_archived_time', ar.last_archived_time,
                         'checkpoint_stats_reset', ck.stats_reset,
                         'wal_stats_reset', wl.stats_reset, 'archiver_stats_reset', ar.stats_reset)::text AS evidence_json,
       'high'::text AS confidence
FROM ck, bg, wl, ar, w;
\echo '@@END PG-INFO-008'

-- ======== PG-INFO-009  P250  Roles summary ========
\echo '@@CHECK PG-INFO-009'
-- check: PG-INFO-009
-- title: Roles summary
-- priority: 250
-- scope: role
-- cost: 0
SELECT 'PG-INFO-009'::text AS check_id,
       'role'::text        AS scope,
       NULL::text          AS object,
       format('%s roles in total: %s can log in, %s are superusers, %s have REPLICATION, %s have CREATEROLE, %s have CREATEDB, %s have BYPASSRLS. %s are PostgreSQL predefined roles (pg_*) and %s are platform-owned. %s login role(s) have a password set, %s have an expiry date. Group roles (no login): %s.',
              c.total, c.login, c.super, c.replication, c.createrole, c.createdb, c.bypassrls,
              c.predefined, c.platform, c.with_password, c.with_expiry, c.total - c.login) AS details,
       json_build_object('total_roles', c.total, 'login_roles', c.login, 'superusers', c.super,
                         'replication_roles', c.replication, 'createrole_roles', c.createrole,
                         'createdb_roles', c.createdb, 'bypassrls_roles', c.bypassrls,
                         'predefined_roles', c.predefined, 'platform_roles', c.platform,
                         'login_roles_with_password', c.with_password,
                         'login_roles_with_expiry', c.with_expiry,
                         'group_roles', c.total - c.login)::text AS evidence_json,
       'high'::text AS confidence
FROM (
  SELECT count(*)                                                        AS total,
         count(*) FILTER (WHERE rolcanlogin)                             AS login,
         count(*) FILTER (WHERE rolsuper)                                AS super,
         count(*) FILTER (WHERE rolreplication)                          AS replication,
         count(*) FILTER (WHERE rolcreaterole)                           AS createrole,
         count(*) FILTER (WHERE rolcreatedb)                             AS createdb,
         count(*) FILTER (WHERE rolbypassrls)                            AS bypassrls,
         count(*) FILTER (WHERE rolname LIKE 'pg\_%')                    AS predefined,
         count(*) FILTER (WHERE rolname IN ('rdsadmin', 'cloudsqladmin', 'cloudsqlsuperuser',
                                            'azure_superuser', 'azure_pg_admin', 'supabase_admin',
                                            'neon_superuser', 'tsdbadmin', 'crunchy_superuser')) AS platform,
         count(*) FILTER (WHERE rolcanlogin AND rolpassword IS NOT NULL) AS with_password,
         count(*) FILTER (WHERE rolcanlogin AND rolvaliduntil IS NOT NULL) AS with_expiry
  FROM pg_roles
) c;
\echo '@@END PG-INFO-009'

-- ======== PG-INFO-010  P250  pg_hba summary ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_info_010 \gset
\if :gate_pg_info_010
\echo '@@CHECK PG-INFO-010'
-- check: PG-INFO-010
-- title: pg_hba summary
-- priority: 250
-- scope: cluster
-- cost: 0
-- min_version: 10
-- requires: superuser
-- Skipped without the privilege to read pg_hba_file_rules; PG-SEC-012 then says so.
SELECT 'PG-INFO-010'::text AS check_id,
       'cluster'::text     AS scope,
       format('%s/%s', r.type, r.auth_method)::text AS object,
       format('%s rule(s) of type %s using method %s. Lines: %s. Addresses: %s. Databases: %s. Roles: %s.%s',
              count(*), r.type, r.auth_method,
              string_agg(r.line_number::text, ', ' ORDER BY r.line_number),
              coalesce(string_agg(DISTINCT coalesce(r.address || coalesce('/' || r.netmask, ''), 'n/a'), ', '), 'n/a'),
              string_agg(DISTINCT array_to_string(r.database, '+'), ', '),
              string_agg(DISTINCT array_to_string(r.user_name, '+'), ', '),
              CASE WHEN count(*) FILTER (WHERE r.error IS NOT NULL) > 0
                   THEN format(' %s of these rules failed to parse: %s',
                               count(*) FILTER (WHERE r.error IS NOT NULL),
                               string_agg(r.error, '; ') FILTER (WHERE r.error IS NOT NULL))
                   ELSE '' END) AS details,
       json_build_object('type', r.type, 'auth_method', r.auth_method, 'rule_count', count(*),
                         'line_numbers', string_agg(r.line_number::text, ';' ORDER BY r.line_number),
                         'addresses', string_agg(DISTINCT coalesce(r.address, ''), ';'),
                         'databases', string_agg(DISTINCT array_to_string(r.database, '+'), ';'),
                         'roles', string_agg(DISTINCT array_to_string(r.user_name, '+'), ';'),
                         'errors', count(*) FILTER (WHERE r.error IS NOT NULL),
                         'listen_addresses', current_setting('listen_addresses'),
                         'ssl', current_setting('ssl'))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_hba_file_rules r
GROUP BY r.type, r.auth_method
ORDER BY min(r.line_number);
\echo '@@END PG-INFO-010'
\else
\echo '@@SKIP PG-INFO-010 needs PostgreSQL 10 or newer'
\endif

-- ======== PG-INFO-011  P250  Tablespaces ========
\echo '@@CHECK PG-INFO-011'
-- check: PG-INFO-011
-- title: Tablespaces
-- priority: 250
-- scope: cluster
-- cost: 0
SELECT 'PG-INFO-011'::text AS check_id,
       'cluster'::text     AS scope,
       t.spcname::text     AS object,
       format('Tablespace %s, owner %s, size %s, location %s. %s database(s) have it as their default. Options: %s. %s',
              t.spcname, pg_get_userbyid(t.spcowner),
              pg_size_pretty(pg_tablespace_size(t.oid)),
              coalesce(nullif(pg_tablespace_location(t.oid), ''), 'inside the data directory'),
              (SELECT count(*) FROM pg_database d WHERE d.dattablespace = t.oid),
              coalesce(array_to_string(t.spcoptions, ', '), 'none (inherits random_page_cost and seq_page_cost from the server)'),
              CASE WHEN pg_tablespace_location(t.oid) <> ''
                   THEN 'A tablespace outside the data directory is usually a different volume, with its own free space, its own latency and its own failure mode - and it must exist and be mounted before the server will start.'
                   ELSE '' END) AS details,
       json_build_object('spcname', t.spcname, 'owner', pg_get_userbyid(t.spcowner),
                         'size_bytes', pg_tablespace_size(t.oid),
                         'location', pg_tablespace_location(t.oid),
                         'spcoptions', array_to_string(t.spcoptions, ';'),
                         'default_for_databases', (SELECT count(*) FROM pg_database d WHERE d.dattablespace = t.oid),
                         'is_external', pg_tablespace_location(t.oid) <> '')::text AS evidence_json,
       'high'::text AS confidence
FROM pg_tablespace t
ORDER BY pg_tablespace_size(t.oid) DESC;
\echo '@@END PG-INFO-011'

-- ======== PG-INFO-012  P250  Statistics window ========
\echo '@@CHECK PG-INFO-012'
-- check: PG-INFO-012
-- title: Statistics window
-- priority: 250
-- scope: cluster
-- cost: 0
-- Printed near the top of the report: every rate in it depends on this window.
WITH resets AS (
  SELECT 'pg_stat_database'  AS view_name, min(stats_reset) AS reset_at FROM pg_stat_database
  UNION ALL
  SELECT 'pg_stat_bgwriter', stats_reset FROM pg_stat_bgwriter
  UNION ALL
  SELECT 'pg_stat_archiver', stats_reset FROM pg_stat_archiver
),
agg AS (
  SELECT min(reset_at) AS earliest, max(reset_at) AS latest,
         string_agg(format('%s=%s', view_name, coalesce(reset_at::text, 'never')), ', ' ORDER BY view_name) AS detail
  FROM resets
)
SELECT 'PG-INFO-012'::text AS check_id,
       'cluster'::text     AS scope,
       NULL::text          AS object,
       format('Counters cover %s days: the earliest statistics reset is %s and the server has been up for %s. Per view: %s. Every rate in this report - checkpoints per hour, deadlocks per day, temp bytes per day, "0 index scans since reset" - is measured over this window and means nothing outside it. A window shorter than 24 hours makes every counter-based finding low confidence; a window of years hides recent change inside a long average.',
              round(extract(epoch FROM now() - coalesce(a.earliest, pg_postmaster_start_time())) / 86400.0, 1)::text,
              coalesce(a.earliest::text, 'unknown (no view reports one)'),
              justify_interval(date_trunc('second', now() - pg_postmaster_start_time())),
              a.detail) AS details,
       json_build_object('earliest_stats_reset', a.earliest,
                         'latest_stats_reset', a.latest,
                         'window_days', round(extract(epoch FROM now() - coalesce(a.earliest, pg_postmaster_start_time())) / 86400.0, 3),
                         'uptime_seconds', round(extract(epoch FROM now() - pg_postmaster_start_time()))::bigint,
                         'postmaster_start_time', pg_postmaster_start_time(),
                         'per_view', a.detail)::text AS evidence_json,
       'high'::text AS confidence
FROM agg a;
\echo '@@END PG-INFO-012'

-- ---- database-scope inventory: run these once per scanned database ----

-- ======== PG-CFG-003  P200  Per-relation storage parameters ========
\echo '@@CHECK PG-CFG-003'
-- check: PG-CFG-003
-- title: Per-relation storage parameters
-- priority: 200
-- scope: relation
-- cost: 1
SELECT 'PG-CFG-003'::text AS check_id,
       'relation'::text   AS scope,
       format('%I.%I.%I', current_database(), n.nspname, c.relname)::text AS object,
       format('%s %s.%s carries storage parameters: %s. Size %s. Per-relation parameters override the server-wide autovacuum and vacuum settings for this object only, so a table that is not being vacuumed the way the global configuration says it should be usually has its answer here (see PG-VAC-009 and PG-VAC-010).',
              CASE c.relkind WHEN 'r' THEN 'Table' WHEN 'p' THEN 'Partitioned table'
                             WHEN 'm' THEN 'Materialized view' WHEN 'i' THEN 'Index'
                             ELSE c.relkind::text END,
              n.nspname, c.relname,
              array_to_string(c.reloptions, ', '),
              pg_size_pretty(pg_total_relation_size(c.oid))) AS details,
       json_build_object('schema', n.nspname, 'relname', c.relname, 'relkind', c.relkind,
                         'reloptions', array_to_string(c.reloptions, ';'),
                         'total_bytes', pg_total_relation_size(c.oid))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace
WHERE c.reloptions IS NOT NULL
  AND n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
ORDER BY pg_total_relation_size(c.oid) DESC;
\echo '@@END PG-CFG-003'

-- ======== PG-IDX-017  P200  Index build in progress ========
SELECT (current_setting('server_version_num')::int >= 120000) AS gate_pg_idx_017 \gset
\if :gate_pg_idx_017
\echo '@@CHECK PG-IDX-017'
-- check: PG-IDX-017
-- title: Index build in progress
-- priority: 200
-- scope: index
-- cost: 0
-- min_version: 12
SELECT 'PG-IDX-017'::text AS check_id,
       'index'::text      AS scope,
       format('%I.%I.%I', current_database(), n.nspname, c.relname)::text AS object,
       format('%s is building an index on %s.%s (pid %s), running for %s. Phase "%s", %s of %s blocks done%s, lockers %s of %s. While this runs it holds a lock on the table, it generates WAL, and a CONCURRENTLY build additionally waits for every transaction older than itself to finish - which is why one long transaction (PG-LOCK-005) can stall it indefinitely. Statement: %s',
              coalesce(nullif(a.application_name, ''), 'A session'),
              n.nspname, c.relname, p.pid,
              justify_interval(date_trunc('second', now() - a.query_start)),
              p.phase,
              to_char(p.blocks_done, 'FM999,999,999,999'), to_char(p.blocks_total, 'FM999,999,999,999'),
              CASE WHEN p.blocks_total > 0
                   THEN ' (' || round(100.0 * p.blocks_done / p.blocks_total, 1)::text || '%)' ELSE '' END,
              p.lockers_done, p.lockers_total,
              left(regexp_replace(coalesce(a.query, ''), '\s+', ' ', 'g'), 200)) AS details,
       json_build_object('pid', p.pid, 'phase', p.phase, 'schema', n.nspname, 'table', c.relname,
                         'blocks_done', p.blocks_done, 'blocks_total', p.blocks_total,
                         'tuples_done', p.tuples_done, 'tuples_total', p.tuples_total,
                         'lockers_done', p.lockers_done, 'lockers_total', p.lockers_total,
                         'current_locker_pid', p.current_locker_pid,
                         'running_seconds', round(extract(epoch FROM now() - a.query_start))::bigint)::text AS evidence_json,
       'high'::text AS confidence
FROM pg_stat_progress_create_index p
JOIN pg_class c     ON c.oid = p.relid
JOIN pg_namespace n ON n.oid = c.relnamespace
JOIN pg_stat_activity a ON a.pid = p.pid;
\echo '@@END PG-IDX-017'
\else
\echo '@@SKIP PG-IDX-017 version-or-role'
\endif

-- ======== PG-SCHEMA-008  P200  Foreign keys or check constraints NOT VALID ========
\echo '@@CHECK PG-SCHEMA-008'
-- check: PG-SCHEMA-008
-- title: Foreign keys or check constraints NOT VALID
-- priority: 200
-- scope: relation
-- cost: 1
SELECT 'PG-SCHEMA-008'::text AS check_id,
       'relation'::text      AS scope,
       format('%I.%I.%I', current_database(), n.nspname, c.relname)::text AS object,
       format('%s constraint %s on %s.%s is NOT VALID: %s. New and modified rows are checked, rows that were already there when it was added never were, so the constraint documents an intention rather than a guarantee - and the planner will not use a NOT VALID check constraint for constraint exclusion. Table size %s. VALIDATE CONSTRAINT scans the table under a SHARE UPDATE EXCLUSIVE lock, which does not block reads or writes, so this is usually a finished migration nobody came back to.',
              CASE con.contype WHEN 'f' THEN 'Foreign-key' WHEN 'c' THEN 'Check' ELSE con.contype::text END,
              con.conname, n.nspname, c.relname,
              pg_get_constraintdef(con.oid),
              pg_size_pretty(pg_total_relation_size(c.oid))) AS details,
       json_build_object('schema', n.nspname, 'table', c.relname,
                         'constraint', con.conname, 'contype', con.contype::text,
                         'definition', pg_get_constraintdef(con.oid),
                         'total_bytes', pg_total_relation_size(c.oid))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_constraint con
JOIN pg_class c     ON c.oid = con.conrelid
JOIN pg_namespace n ON n.oid = c.relnamespace
WHERE NOT con.convalidated
  AND n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
ORDER BY pg_total_relation_size(c.oid) DESC;
\echo '@@END PG-SCHEMA-008'

-- ======== PG-SCHEMA-012  P200  Legacy inheritance-based partitioning ========
SELECT (current_setting('server_version_num')::int >= 100000) AS gate_pg_schema_012 \gset
\if :gate_pg_schema_012
\echo '@@CHECK PG-SCHEMA-012'
-- check: PG-SCHEMA-012
-- title: Legacy inheritance-based partitioning
-- priority: 200
-- scope: relation
-- cost: 1
-- min_version: 10
SELECT 'PG-SCHEMA-012'::text AS check_id,
       'relation'::text      AS scope,
       format('%I.%I.%I', current_database(), n.nspname, c.relname)::text AS object,
       format('Table %s.%s is the parent of %s child table(s) through table inheritance, not declarative partitioning: it has no entry in pg_partitioned_table. Children total %s. Row routing therefore depends on triggers or rules that the application or a migration installed, pruning depends on constraint_exclusion (currently %s) finding usable CHECK constraints rather than on partition bounds, and there is no ATTACH or DETACH PARTITION. Inventory row: this pattern still works, and converting it is a planned migration rather than a fix.',
              n.nspname, c.relname, cnt.n, pg_size_pretty(cnt.total_bytes),
              current_setting('constraint_exclusion')) AS details,
       json_build_object('schema', n.nspname, 'table', c.relname,
                         'child_count', cnt.n, 'children_bytes', cnt.total_bytes,
                         'constraint_exclusion', current_setting('constraint_exclusion'),
                         'trigger_count', (SELECT count(*) FROM pg_trigger tg
                                           WHERE tg.tgrelid = c.oid AND NOT tg.tgisinternal))::text AS evidence_json,
       'high'::text AS confidence
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace
CROSS JOIN LATERAL (
  SELECT count(*) AS n, coalesce(sum(pg_total_relation_size(i.inhrelid)), 0) AS total_bytes
  FROM pg_inherits i WHERE i.inhparent = c.oid
) cnt
WHERE cnt.n > 0
  AND NOT EXISTS (SELECT 1 FROM pg_partitioned_table p WHERE p.partrelid = c.oid)
  AND n.nspname NOT IN ('pg_catalog', 'information_schema')
ORDER BY cnt.total_bytes DESC;
\echo '@@END PG-SCHEMA-012'
\else
\echo '@@SKIP PG-SCHEMA-012 version-or-role'
\endif

-- ======== PG-QRY-003  P240  Top 10 statements by total execution time ========
\echo '@@CHECK PG-QRY-003'
-- check: PG-QRY-003
-- title: Top 10 statements by total execution time
-- priority: 240
-- scope: query
-- cost: 1
-- thresholds: top_n
-- Requires pg_stat_statements in this database; PG-QRY-001 fires when it is absent.
\set ON_ERROR_STOP off
SELECT (to_regclass('pg_stat_statements') IS NOT NULL) AS pg_qry_003_pgss \gset
\if :pg_qry_003_pgss
SELECT EXISTS (SELECT 1 FROM pg_attribute
               WHERE attrelid = to_regclass('pg_stat_statements')
                 AND attname = 'total_exec_time' AND NOT attisdropped) AS pg_qry_003_v18 \gset
SELECT EXISTS (SELECT 1 FROM pg_attribute
               WHERE attrelid = to_regclass('pg_stat_statements')
                 AND attname = 'wal_bytes' AND NOT attisdropped) AS pg_qry_003_has_wal \gset
WITH q AS (
\if :pg_qry_003_v18
  SELECT queryid, query, calls, rows,
         total_exec_time::numeric AS total_ms, mean_exec_time::numeric AS mean_ms, stddev_exec_time::numeric AS stddev_ms,
         shared_blks_read, shared_blks_hit, temp_blks_read, temp_blks_written,
\if :pg_qry_003_has_wal
         wal_bytes, wal_records,
\else
         0::numeric AS wal_bytes, 0::bigint AS wal_records,
\endif
         userid, dbid
  FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())
\else
  SELECT queryid, query, calls, rows,
         total_time::numeric AS total_ms, mean_time::numeric AS mean_ms, stddev_time::numeric AS stddev_ms,
         shared_blks_read, shared_blks_hit, temp_blks_read, temp_blks_written,
         0::numeric AS wal_bytes, 0::bigint AS wal_records,
         userid, dbid
  FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())
\endif
),
tot AS (SELECT sum(total_ms) AS all_ms, sum(calls) AS all_calls FROM q)

SELECT 'PG-QRY-003'::text AS check_id,
       'query'::text   AS scope,
       ('queryid:' || q.queryid::text)::text AS object,
       format('#%s by total execution time: %s ms total. %s calls, mean %s ms, %s rows per call, %s%% of total execution time on this database. Shared blocks: %s read, %s hit. Temp blocks written: %s.%s Statement (normalised, first 300 characters): %s',
              row_number() OVER (ORDER BY q.total_ms DESC),
              to_char(round(q.total_ms), 'FM999,999,999,999'),
              to_char(q.calls, 'FM999,999,999,999'),
              round(q.mean_ms, 2)::text,
              round(q.rows::numeric / nullif(q.calls, 0), 1)::text,
              round(100.0 * q.total_ms / nullif(t.all_ms, 0), 1)::text,
              to_char(q.shared_blks_read, 'FM999,999,999,999'),
              to_char(q.shared_blks_hit, 'FM999,999,999,999'),
              to_char(q.temp_blks_written, 'FM999,999,999,999'),
              CASE WHEN q.wal_bytes > 0 THEN ' WAL generated: ' || pg_size_pretty(q.wal_bytes::bigint) || '.' ELSE '' END,
              left(regexp_replace(q.query, '\s+', ' ', 'g'), 300)) AS details,
       json_build_object('queryid', q.queryid, 'calls', q.calls, 'rows', q.rows,
                         'total_ms', round(q.total_ms, 2), 'mean_ms', round(q.mean_ms, 3),
                         'stddev_ms', round(q.stddev_ms, 3),
                         'pct_of_total_time', round(100.0 * q.total_ms / nullif(t.all_ms, 0), 2),
                         'shared_blks_read', q.shared_blks_read, 'shared_blks_hit', q.shared_blks_hit,
                         'temp_blks_read', q.temp_blks_read, 'temp_blks_written', q.temp_blks_written,
                         'wal_bytes', q.wal_bytes::bigint, 'wal_records', q.wal_records,
                         'usename', (SELECT rolname FROM pg_roles WHERE oid = q.userid),
                         'query', left(regexp_replace(q.query, '\s+', ' ', 'g'), 300))::text AS evidence_json,
       'medium'::text AS confidence
FROM q CROSS JOIN tot t
ORDER BY q.total_ms DESC
LIMIT :'pg_qry_003_top_n'::int;
\endif
\echo '@@END PG-QRY-003'

-- ======== PG-QRY-004  P240  Top 10 statements by mean execution time ========
\echo '@@CHECK PG-QRY-004'
-- check: PG-QRY-004
-- title: Top 10 statements by mean execution time
-- priority: 240
-- scope: query
-- cost: 1
-- thresholds: top_n, min_calls
-- Requires pg_stat_statements in this database; PG-QRY-001 fires when it is absent.
\set ON_ERROR_STOP off
SELECT (to_regclass('pg_stat_statements') IS NOT NULL) AS pg_qry_004_pgss \gset
\if :pg_qry_004_pgss
SELECT EXISTS (SELECT 1 FROM pg_attribute
               WHERE attrelid = to_regclass('pg_stat_statements')
                 AND attname = 'total_exec_time' AND NOT attisdropped) AS pg_qry_004_v18 \gset
SELECT EXISTS (SELECT 1 FROM pg_attribute
               WHERE attrelid = to_regclass('pg_stat_statements')
                 AND attname = 'wal_bytes' AND NOT attisdropped) AS pg_qry_004_has_wal \gset
WITH q AS (
\if :pg_qry_004_v18
  SELECT queryid, query, calls, rows,
         total_exec_time::numeric AS total_ms, mean_exec_time::numeric AS mean_ms, stddev_exec_time::numeric AS stddev_ms,
         shared_blks_read, shared_blks_hit, temp_blks_read, temp_blks_written,
\if :pg_qry_004_has_wal
         wal_bytes, wal_records,
\else
         0::numeric AS wal_bytes, 0::bigint AS wal_records,
\endif
         userid, dbid
  FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())
\else
  SELECT queryid, query, calls, rows,
         total_time::numeric AS total_ms, mean_time::numeric AS mean_ms, stddev_time::numeric AS stddev_ms,
         shared_blks_read, shared_blks_hit, temp_blks_read, temp_blks_written,
         0::numeric AS wal_bytes, 0::bigint AS wal_records,
         userid, dbid
  FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())
\endif
),
tot AS (SELECT sum(total_ms) AS all_ms, sum(calls) AS all_calls FROM q)

SELECT 'PG-QRY-004'::text AS check_id,
       'query'::text   AS scope,
       ('queryid:' || q.queryid::text)::text AS object,
       format('#%s by mean execution time: %s ms per call. %s calls, mean %s ms, %s rows per call, %s%% of total execution time on this database. Shared blocks: %s read, %s hit. Temp blocks written: %s.%s Statement (normalised, first 300 characters): %s',
              row_number() OVER (ORDER BY q.mean_ms DESC),
              round(q.mean_ms, 2)::text,
              to_char(q.calls, 'FM999,999,999,999'),
              round(q.mean_ms, 2)::text,
              round(q.rows::numeric / nullif(q.calls, 0), 1)::text,
              round(100.0 * q.total_ms / nullif(t.all_ms, 0), 1)::text,
              to_char(q.shared_blks_read, 'FM999,999,999,999'),
              to_char(q.shared_blks_hit, 'FM999,999,999,999'),
              to_char(q.temp_blks_written, 'FM999,999,999,999'),
              CASE WHEN q.wal_bytes > 0 THEN ' WAL generated: ' || pg_size_pretty(q.wal_bytes::bigint) || '.' ELSE '' END,
              left(regexp_replace(q.query, '\s+', ' ', 'g'), 300)) AS details,
       json_build_object('queryid', q.queryid, 'calls', q.calls, 'rows', q.rows,
                         'total_ms', round(q.total_ms, 2), 'mean_ms', round(q.mean_ms, 3),
                         'stddev_ms', round(q.stddev_ms, 3),
                         'pct_of_total_time', round(100.0 * q.total_ms / nullif(t.all_ms, 0), 2),
                         'shared_blks_read', q.shared_blks_read, 'shared_blks_hit', q.shared_blks_hit,
                         'temp_blks_read', q.temp_blks_read, 'temp_blks_written', q.temp_blks_written,
                         'wal_bytes', q.wal_bytes::bigint, 'wal_records', q.wal_records,
                         'usename', (SELECT rolname FROM pg_roles WHERE oid = q.userid),
                         'query', left(regexp_replace(q.query, '\s+', ' ', 'g'), 300))::text AS evidence_json,
       'medium'::text AS confidence
FROM q CROSS JOIN tot t
WHERE q.calls >= :'pg_qry_004_min_calls'::bigint
ORDER BY q.mean_ms DESC
LIMIT :'pg_qry_004_top_n'::int;
\endif
\echo '@@END PG-QRY-004'

